 3	final class InsertionSortAlgorithm {
 4	
 5	    private InsertionSortAlgorithm() {
 6	        // Utility class.
 7	    }
 8	
 9	    static void sort(IntArraySlice slice) {
10	        if (slice.hasFewerThanTwoElements()) {
11	            return;
12	        }
13	
14	        for (int currentIndex = slice.startInclusive() + 1;
15	                currentIndex < slice.endExclusive();
16	                currentIndex++) {
17	            insertValue(slice, currentIndex);
18	        }
19	    }
20	
21	    static boolean isSorted(IntArraySlice slice) {
22	        for (int index = slice.startInclusive() + 1; index < slice.endExclusive(); index++) {
23	            if (slice.valueAt(index - 1) > slice.valueAt(index)) {
24	                return false;
25	            }
26	        }
27	
28	        return true;
29	    }
30	
31	    private static void insertValue(IntArraySlice slice, int currentIndex) {
32	        int valueToInsert = slice.valueAt(currentIndex);
33	        int insertionIndex = findInsertionIndex(slice, currentIndex, valueToInsert);
34	
35	        slice.shiftRight(insertionIndex, currentIndex);
36	        slice.setValueAt(insertionIndex, valueToInsert);
37	    }
38	
39	    private static int findInsertionIndex(IntArraySlice slice, int currentIndex, int valueToInsert) {
40	        int scanIndex = currentIndex - 1;
41	
42	        while (scanIndex >= slice.startInclusive() && slice.valueAt(scanIndex) > valueToInsert) {
43	            scanIndex--;
44	        }
45	
46	        return scanIndex + 1;
47	    }
48	}

